"""Practice material for memory jogging: flashcards, extra quiz questions and exercises.

Everything is keyed by course slug. Cards and questions are matched by `key` when seeding,
so a learner's review history survives edits. Lesson quizzes are added to the question bank
automatically by `manage.py seed`, so only *extra* questions are listed here.

Exercise `data` uses exactly the same shapes as lessons of the same kind (see README).
"""


def card(key, front, back):
    return {"key": key, "front": front, "back": back}


def q(key, question, options, answer, explain=""):
    return {"key": key, "question": question, "options": options, "answer": answer, "explain": explain}


def typing_ex(key, title, content, text, keys, target_wpm, target_acc=88, minutes=4):
    return {"key": key, "title": title, "kind": "typing", "minutes": minutes, "content": content,
            "data": {"text": text, "keys": keys, "targetWpm": target_wpm, "targetAccuracy": target_acc}}


def word_ex(key, title, content, starter_html, tasks, minutes=6):
    return {"key": key, "title": title, "kind": "word", "minutes": minutes, "content": content,
            "data": {"starterHtml": starter_html, "tasks": tasks}}


def code_ex(key, title, content, starter, tests, solution, minutes=6):
    return {"key": key, "title": title, "kind": "code", "minutes": minutes, "content": content,
            "data": {"starter": starter, "tests": tests, "solution": solution}}


def web_ex(key, title, content, html, css, checks, js="", minutes=8):
    return {"key": key, "title": title, "kind": "web", "minutes": minutes, "content": content,
            "data": {"html": html, "css": css, "js": js, "checks": checks}}


